/**
 * Campaign mode — 21 hand-tuned scenarios (3 acts per sin) plus framing.
 *
 * Each mission specifies:
 *  - the player's forced sin + a 30-card deck built from a `DeckArchetype`
 *  - a boss with a forced sin, 30-card deck (always containing exactly one
 *    twist card from `bossCards.ts`), an HP boost, and a thematic archetype
 *  - hand-written intro / outro / defeat lines (the "framing"); mid-fight
 *    quips are still generated by `aiNarrator.ts` ("AI flourishes")
 *  - linear unlock chain via `unlockedBy`
 *
 * Player progression across an act: `starter` → `balanced` → `elite`.
 * Boss progression varies by sin: damage-themed sins escalate to
 * `aggressive` then `elite`; defensive sins (Sloth) lean `control`.
 */

import { ALL_DECKS } from "./cardData";
import type { CardDefinition, SinType } from "./gameTypes";
import { BOSS_CARDS } from "./bossCards";

export interface CampaignBoss {
  /** Display name shown above the boss portrait. */
  name: string;
  /** Boss's faction. Often matches the mission sin (mirror match) but doesn't have to. */
  sin: SinType;
  /** Title/epithet rendered as a subtitle. */
  epithet: string;
  /** 30-card deck. Must contain exactly one boss twist card ID. */
  deck: string[];
  /**
   * Bonus HP added on top of `STARTING_HP` after the engine initialises the
   * game. Use sparingly — acts 1 should usually be 0 (let the player learn
   * the matchup), acts 2/3 lean on this to pace the difficulty curve.
   */
  hpBoost?: number;
}

export interface CampaignMission {
  id: string;
  sin: SinType;
  act: 1 | 2 | 3;
  /** Mission title shown on the selector tile and the intro overlay. */
  title: string;
  /** One-sentence hook on the selector tile. */
  hook: string;
  /** Pre-fight narrator monologue (3–6 sentences). */
  intro: string;
  /** Victory narrator outro (2–4 sentences). */
  outro: string;
  /** Defeat narrator line (1–2 sentences). */
  defeatLine: string;
  /** Player's forced sin — they cannot choose a different one. */
  playerDeck: string[];
  boss: CampaignBoss;
  /** Mission ID that must be completed first. `null` = always available. */
  unlockedBy: string | null;
  /** When true, the mission shows in the selector but cannot be started. */
  comingSoon?: boolean;
}

// ─── Deck archetypes ─────────────────────────────────────────────
//
// Every player and boss deck is built by picking 30 cards from the
// faction's 60-card PvP pool through one of these archetype filters.
// All builders are deterministic — they don't shuffle (the engine does
// that on `startGame`). Order matters for the boss-twist seeding only,
// not for gameplay.

export type DeckArchetype =
  | "starter"      // Act 1 players: cheap cards, no epics, easy to learn
  | "balanced"     // Act 2 players / many Act 1 bosses: even mix
  | "aggressive"   // damage-leaning Act 2/3 bosses
  | "control"      // Sloth-style bosses: slowburn + defensive
  | "elite";       // Act 3 bosses + Act 3 player: full power

const DEFENSIVE_EFFECTS = new Set([
  "shield_gain",
  "shield_steal",
  "heal_block",
  "heal_gain",
  "energy_block",
] as const);

function pickStarter(pool: CardDefinition[]): CardDefinition[] {
  // Bias toward cost 0–3, no epics. Tutorial-friendly.
  const targets: { cost: number; count: number }[] = [
    { cost: 0, count: 8 },
    { cost: 1, count: 10 },
    { cost: 2, count: 8 },
    { cost: 3, count: 4 },
  ];
  const result: CardDefinition[] = [];
  const used = new Set<string>();
  for (const { cost, count } of targets) {
    pool
      .filter((c) => c.cost === cost && c.tier !== "epic" && !used.has(c.id))
      .slice(0, count)
      .forEach((c) => {
        result.push(c);
        used.add(c.id);
      });
  }
  // Pad if any cost bucket was undersized (some factions have fewer cost-3 commons).
  for (const c of pool) {
    if (result.length >= 30) break;
    if (used.has(c.id) || c.tier === "epic") continue;
    result.push(c);
    used.add(c.id);
  }
  return result.slice(0, 30);
}

function pickBalanced(pool: CardDefinition[]): CardDefinition[] {
  // Roughly the natural tier distribution: ~6 epic, ~10 rare, ~14 common.
  const epics = pool.filter((c) => c.tier === "epic").slice(0, 6);
  const rares = pool.filter((c) => c.tier === "rare").slice(0, 10);
  const commons = pool.filter((c) => c.tier === "common").slice(0, 14);
  return [...epics, ...rares, ...commons].slice(0, 30);
}

function pickAggressive(pool: CardDefinition[]): CardDefinition[] {
  // Bias toward aggressive compound pattern + epic damage cards.
  const aggressive = pool.filter((c) => c.compoundPattern === "aggressive");
  const aggrSet = new Set(aggressive.map((c) => c.id));
  const damageEpics = pool.filter(
    (c) =>
      !aggrSet.has(c.id) &&
      c.tier === "epic" &&
      c.effects.some((e) => e.type === "damage")
  );
  const damageEpicSet = new Set(damageEpics.map((c) => c.id));
  const damageRares = pool.filter(
    (c) =>
      !aggrSet.has(c.id) &&
      !damageEpicSet.has(c.id) &&
      c.tier === "rare" &&
      c.effects.some((e) => e.type === "damage")
  );
  const damageRareSet = new Set(damageRares.map((c) => c.id));
  const rest = pool.filter(
    (c) => !aggrSet.has(c.id) && !damageEpicSet.has(c.id) && !damageRareSet.has(c.id)
  );
  return [...aggressive, ...damageEpics, ...damageRares, ...rest].slice(0, 30);
}

function pickControl(pool: CardDefinition[]): CardDefinition[] {
  // Bias toward slowburn pattern + defensive effects.
  const slowburn = pool.filter((c) => c.compoundPattern === "slowburn");
  const slowSet = new Set(slowburn.map((c) => c.id));
  const defensive = pool.filter(
    (c) =>
      !slowSet.has(c.id) &&
      c.effects.some((e) => DEFENSIVE_EFFECTS.has(e.type as never))
  );
  const defSet = new Set(defensive.map((c) => c.id));
  const rest = pool.filter((c) => !slowSet.has(c.id) && !defSet.has(c.id));
  return [...slowburn, ...defensive, ...rest].slice(0, 30);
}

function pickElite(pool: CardDefinition[]): CardDefinition[] {
  // All 12 epics, then top rares by cost, then highest-cost commons.
  const epics = pool.filter((c) => c.tier === "epic");
  const rares = [...pool.filter((c) => c.tier === "rare")].sort((a, b) => b.cost - a.cost);
  const commons = [...pool.filter((c) => c.tier === "common")].sort((a, b) => b.cost - a.cost);
  return [...epics, ...rares, ...commons].slice(0, 30);
}

const ARCHETYPE_PICKERS: Record<DeckArchetype, (pool: CardDefinition[]) => CardDefinition[]> = {
  starter: pickStarter,
  balanced: pickBalanced,
  aggressive: pickAggressive,
  control: pickControl,
  elite: pickElite,
};

/** Build a 30-card player deck for a sin + archetype combination. */
export function buildArchetypeDeck(sin: SinType, archetype: DeckArchetype): string[] {
  const pool = ALL_DECKS[sin];
  return ARCHETYPE_PICKERS[archetype](pool).map((c) => c.id);
}

/**
 * Build a 30-card boss deck: pick 29 cards from the archetype, then prepend
 * the boss's twist card so it sits at index 0 before the engine shuffles.
 */
function buildBossDeck(
  sin: SinType,
  archetype: DeckArchetype,
  twistCardId: string
): string[] {
  const base = buildArchetypeDeck(sin, archetype);
  return [twistCardId, ...base.slice(0, 29)];
}

// ─── Backwards-compat call-site shims ────────────────────────────
//
// The 21 mission constants were originally authored against
// `playerStarterDeck(sin)` and `bossDeck(sin, twistCardId)`. Now that
// every player+boss pairing has an archetype, these shims accept an
// optional archetype so we don't have to rewrite every mission entry —
// just pass an archetype on Act 2 / 3 calls.

function playerStarterDeck(
  sin: SinType,
  archetype: DeckArchetype = "starter"
): string[] {
  return buildArchetypeDeck(sin, archetype);
}

function bossDeck(
  sin: SinType,
  twistCardId: string,
  archetype: DeckArchetype = "balanced"
): string[] {
  return buildBossDeck(sin, archetype, twistCardId);
}

// ─── Stub builder (kept for future stubbed missions) ─────────────

function stub(id: string, sin: SinType, act: 1 | 2 | 3, title: string, hook: string): CampaignMission {
  return {
    id,
    sin,
    act,
    title,
    hook,
    intro: "(Coming soon — this scenario hasn't been written yet.)",
    outro: "",
    defeatLine: "",
    playerDeck: playerStarterDeck(sin),
    boss: {
      name: "TBD",
      sin,
      epithet: "TBD",
      deck: playerStarterDeck(sin),
    },
    unlockedBy: act === 1 ? null : `${sin}_${act - 1}`,
    comingSoon: true,
  };
}

