const MISSIONS_BY_ID: Record<string, CampaignMission> = Object.fromEntries(
  CAMPAIGN_MISSIONS.map((m) => [m.id, m])
);

export function getMissionById(id: string): CampaignMission | undefined {
  return MISSIONS_BY_ID[id];
}

export function getMissionsForSin(sin: SinType): CampaignMission[] {
  return CAMPAIGN_MISSIONS.filter((m) => m.sin === sin).sort((a, b) => a.act - b.act);
}

/** Player has completed a mission if its id is in the completed set. */
export function isMissionUnlocked(
  mission: CampaignMission,
  completedIds: ReadonlySet<string>
): boolean {
  if (mission.comingSoon) return false;
  if (mission.unlockedBy === null) return true;
  return completedIds.has(mission.unlockedBy);
}

/**
 * Pick the mission to surface as a "Continue" CTA. Returns null when the
 * player has no campaign history yet (the Home page just shows the regular
 * "Campaign" tile in that case).
 *
 * Priority:
 *  1. An attempted-but-not-yet-cleared mission (player hit a wall — give
 *     them a one-click jump back to it).
 *  2. The next unlocked + uncompleted mission after a cleared streak
 *     (player wants to keep going).
 *
 * `attempts` carries the number of launches per mission ID and comes from
 * `useCampaignProgress`. `completedIds` is the cleared-mission set from
 * the same hook.
 */
export function getContinueMission(
  attempts: ReadonlyMap<string, number> | Record<string, number>,
  completedIds: ReadonlySet<string>
): CampaignMission | null {
  const attemptsMap =
    attempts instanceof Map
      ? attempts
      : new Map(Object.entries(attempts));

  // Case 1 — a mission has been attempted but not cleared.
  for (const m of CAMPAIGN_MISSIONS) {
    if (m.comingSoon) continue;
    if (completedIds.has(m.id)) continue;
    if ((attemptsMap.get(m.id) ?? 0) > 0) return m;
  }

  // Case 2 — at least one mission cleared. Suggest the next available act.
  if (completedIds.size > 0) {
    for (const m of CAMPAIGN_MISSIONS) {
      if (m.comingSoon) continue;
      if (completedIds.has(m.id)) continue;
      if (isMissionUnlocked(m, completedIds)) return m;
    }
  }

  return null;
}

/** Twist card IDs referenced by missions, for test integrity checks. */
export const ALL_TWIST_CARD_IDS = new Set(BOSS_CARDS.map((c) => c.id));

// ─── Difficulty surfacing ────────────────────────────────────────
//
// Difficulty is computed (not hand-authored) so it stays in sync if we
// retune HP boosts or boss archetypes. Five tiers, mapped to a 1–5 star
// rating + a flavour label rendered on the selector tile and the intro
// panel.

export interface MissionDifficulty {
  /** 1–5 stars. */
  stars: number;
  /** Short flavour label for the chip ("Initiate", "Apex", …). */
  label: string;
  /** Hex accent colour matching the difficulty's palette. */
  accent: string;
}

const DIFFICULTY_LABELS: Record<number, string> = {
  1: "Initiate",
  2: "Apprentice",
  3: "Adept",
  4: "Reckoning",
  5: "Apex",
};

const DIFFICULTY_ACCENTS: Record<number, string> = {
  1: "#34d399", // emerald — easy
  2: "#fbbf24", // amber — easy-medium
  3: "#fb923c", // orange — medium
  4: "#f87171", // red — hard
  5: "#dc2626", // deep red — hardest
};

export function getMissionDifficulty(mission: CampaignMission): MissionDifficulty {
  // Base from act: 2 / 3 / 5 stars. Bumped to 4 for Act 2s with high HP boost
  // so the curve has room to vary without hand-authoring per mission.
  let stars = mission.act === 1 ? 2 : mission.act === 2 ? 3 : 5;
  if (mission.act === 2 && (mission.boss.hpBoost ?? 0) >= 100) stars = 4;
  stars = Math.min(5, Math.max(1, stars));
  return {
    stars,
    label: DIFFICULTY_LABELS[stars] ?? "Adept",
    accent: DIFFICULTY_ACCENTS[stars] ?? "#fb923c",
  };
}
